/* ── ENGINE ──────────────────────────────────────────────────────
   Intent matching over the answer bank plus the records above.
   Exact phrases beat signal words, rare words beat common ones, and
   the bank's tie-break rules are applied as boosts. The decision
   order on a weak match: Ace trivia, small talk, then OTHER for
   site-flavoured questions, and the nonsense line (with context-aware
   suggestions) only when nothing connects at all. */
const normalize=s=>s.toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9$]+/g,' ').trim();
const stop=new Set('a an the is are was were be been am i me my you your he his him it its they them their this that to for of on in with and or as at do does did can could would should will very really please want need know more some much just so what how why where when who which tell'.split(' '));
/* Plural 's' before 'es': "conferences" must meet "conference", and the
   'es' rule got there first and left "conferenc". */
const stem=t=>{if(t.length>5&&t.endsWith('ing'))return t.slice(0,-3);if(t.length>4&&t.endsWith('ed'))return t.slice(0,-2);if(t.length>3&&t.endsWith('s')&&!t.endsWith('ss'))return t.slice(0,-1);return t;};
const tokens=s=>normalize(s).split(' ').filter(t=>t.length>1&&!stop.has(t)).map(stem);

/* One searchable doc per intent and per record. */
const docs=[];
for(const it of INTENTS){
  if(it.id==='NONSENSE'||it.id==='SMALL_TALK')continue;   // reached by fallback, never by scoring
  docs.push({kind:'intent',id:it.id,phrases:it.phrases.map(normalize),
    words:new Set([].concat(...it.signals.concat(it.extra).filter(s=>!s.includes(' ')).map(tokens))),
    wordPhrases:it.signals.concat(it.extra).filter(s=>s.includes(' ')).map(normalize)});
}
for(const r of records){
  docs.push({kind:'record',id:r.id,phrases:r.aliases.filter(a=>a.includes(' ')).map(normalize),
    words:new Set([].concat(...r.aliases.filter(a=>!a.includes(' ')).map(tokens))),
    wordPhrases:[]});
}
/* Rarity: a word found in many docs says little about any of them. */
const df=new Map();
for(const d of docs){const seen=new Set(d.words);for(const p of d.phrases.concat(d.wordPhrases))for(const t of tokens(p))seen.add(t);for(const t of seen)df.set(t,(df.get(t)||0)+1);}
const idf=t=>{const n=df.get(t)||0;return Math.log(1+docs.length/(n+1));};
const close=(a,b)=>{ // one edit OR one swapped pair, same first letter
  if(a===b)return true;if(a[0]!==b[0]||Math.abs(a.length-b.length)>1||a.length<4)return false;
  if(a.length===b.length){ // adjacent transposition: "investmnet" -> "investment"
   let d=[];for(let i=0;i<a.length;i++)if(a[i]!==b[i])d.push(i);
   if(d.length===2&&d[1]===d[0]+1&&a[d[0]]===b[d[1]]&&a[d[1]]===b[d[0]])return true;
  }
  let i=0,j=0,e=0;while(i<a.length&&j<b.length){if(a[i]===b[j]){i++;j++;continue;}if(++e>1)return false;
    if(a.length>b.length)i++;else if(b.length>a.length)j++;else{i++;j++;}}
  return e+(a.length-i)+(b.length-j)<=1;};

/* Every word the bank knows, unstemmed: the spelling dictionary. A typo is
   repaired in the QUESTION before anything else runs, so "pokr night" can
   still hit the phrase "poker night" and "rescedule" can still fire the
   reschedule rule — neither of which a word-by-word fuzzy match reaches. */
const VOCAB=new Set();
for(const d of docs){for(const t of d.words)VOCAB.add(t);
  for(const p of d.phrases.concat(d.wordPhrases))for(const w of normalize(p).split(' '))if(w.length>2)VOCAB.add(w);}
for(const w of 'ace aces matthew ferguson spaders cybertruck mastermind advisory poker running networking membership meeting session commitment assistant vancouver langley eventbrite'.split(' '))VOCAB.add(w);
/* Shorthand and short typos fuzzy matching can't reach safely: four-letter
   words are too easy to "correct" into the wrong thing ("cars" -> "cards"),
   so those are listed by hand instead. */
const FIXUPS={wat:'what',wot:'what',whut:'what',hw:'how',ho:'how',u:'you',ur:'your',r:'are',pls:'please',plz:'please',thx:'thanks',ty:'thanks',abt:'about',bc:'because',pokr:'poker',buyin:'buy in',cybertruk:'cybertruck',cybertrk:'cybertruck',masterming:'mastermind',mastrmind:'mastermind',advisery:'advisory',adviser:'advisor',mtg:'meeting',appt:'appointment',info:'information',mcuh:'much',muc:'much',trck:'truck',bok:'book',boking:'booking',costs:'cost',prise:'price',adv:'advisory',memb:'membership',dose:'does',gme:'game',gmae:'game',gaem:'game',gmes:'games',dev:'development',wanna:'want to',gonna:'going to'};
const SHORT=['staff','team','cost','fees','price','help','meet','book','join','apply','event','poker','truck','ace','time','call','hire','sell','grow'];
/* Real four-letter words are never "corrected": "feel" is one edit from
   "fees" and was sending "I feel like a failure" to the price list. */
const COMMON4=new Set('aces feel fear fell felt feed free fuel full fine five food foot form four gone good grew hate here high hold home hope hour idea into just keep kind know last late lead left less life like line list live long look lose lost love made make many mean more most move much must name near next nice note once only open over past plan play read real rest rich ride risk road role room rule safe said same save seem seen self send sent ship shop show side sign site size slow some soon sort stay step stop such sure take talk tell than that them then they this told took tour town trip true turn type used very view wait walk wall want week well went were what when wife will wish with word work year your cash case cars card sale cool deal done fail fast fire firm fund gave gets give goal grow hand hard head hear held hint huge hurt jobs kids lady land lent loan lots mind miss mine news paid part pass pays pick poor push quit rate rent sick sold star term test tips tool upon vote wage wins wood zero'.split(' '));
/* Everyday -ing words that sit one letter from a site word ("buying" ->
   "buyin" sent a hotel purchase to poker night). */
const PROTECT=new Set('promise promises promised stuff wedding weddings buying minute minutes thanks thank selling hiring firing opening closing moving building thinking looking wanting trying having making getting running'.split(' '));
function despell(q){
  return q.split(' ').map(w=>{
    if(FIXUPS[w])return FIXUPS[w];if(PROTECT.has(w))return w;
    /* Four-letter words are only corrected against this short list: fuzzy
       matching at that length turns "cars" into "cards" and sends someone
       asking about their car to poker night. */
    if(w.length===4){if(COMMON4.has(w))return w;for(const v of SHORT){if(close(w,v))return v;}return w;}
    if(w.length<5||VOCAB.has(w))return w;
    /* Try the dictionary before accepting a word on its stem alone:
       "runing" stems to "run", which IS known, and that used to hide the
       real fix ("running") from the phrase and rule passes. */
    /* Never "correct" a word into its own prefix: "included" is not a typo
       for "include", and rewriting it broke the follow-up patterns. */
    for(const v of VOCAB){if(v.length<w.length&&w.startsWith(v))continue;if(close(w,v))return v;}
    return w;
  }).join(' ');
}

