const STRONG=new Set(['RESCHEDULE','OTHER','PROFESSIONAL_ADVICE','TRANSPORT_BOOKING','SPEAKING_BOOKING','GROUP_BOOKING','AVAILABILITY','JOBS','MEET_INFORMALLY','OVERVIEW','running','networking','transport','MASTERMIND','membership-benefits','EVENT_DETAILS','ONGOING','WHO_IS_HE','currency',
  'VS_CONSULTANT','BRING_PARTNER','WHO_MADE_YOU','MEMORY','ACE_FAMILY','RUN_DOGS_KIDS','RUN_DISTANCE','POKER_LEGAL','FLIRT','HUMAN','SIZE','MEETING_LENGTH','READY_TO_BUY','VS_PEER_GROUP','INVESTOR_BOARD','PHONE','HOURS','MLM','PROMPT_INJECTION','HARD_TIMES','SCARED_TO_ASK','INCORPORATE_TAX','THINK_ABOUT_IT','MAYBE_LATER','MOST_POPULAR','JOKE','ACT_FOR_ME','PRESS_KIT','UNSUBSCRIBE','OWN_BUSINESS','FORM_BROKEN','ACE_PERSONALITY','ACE_FUN','WHAT_CAN_YOU_DO']);

/* Successive questions. "What's it for?" means nothing alone — it means
   whatever was just answered. FOLLOWUPS (from the bank's Set 5) holds the
   wording per topic; these patterns say which line to use. */
const FOLLOW_MORE={MASTERMIND:'membership-benefits',CYBERTRUCK:'transport',EVENTS:'events',ON_SITE:'scout',ONGOING:'advisory'};
/* Order matters: "why is it so much" must reach why_so_much, not how_much. */
const FOLLOW_KIND=[
 ['really',/^(really|seriously|no way|for real|are you sure|you sure)\b/],
 ['anything_else',/anything else|what else (can|do) you|any other|thats it\?/],
 ['why_so_much',/why (is it |does it cost |are they )?(so|that) (much|expensive|high)|why so much|thats (a lot|expensive|steep|pricey)|seems expensive/],
 ['worth_it',/worth it\b|worth the money|worth paying|any good\b|worth \$?\d+|\b(vs|versus|instead of|better than|compared to|or) (an? )?(uber|lyft|taxi|rideshare|limo)\b|\b(uber|lyft|taxi|rideshare|limo)\b.{0,6}\b(vs|versus|or)\b/],
 ['both',/member(s)? (get|have|pay|use)|member (rate|discount|price|pricing)|discount for members|members discount|\bboth\b|at the same time|as well as|alongside (it|that)|do i have to (choose|pick)/],
 ['what_if',/what if\b|what happens if\b|cant make|can not make|miss (a|the|one)|not approved|dont like it|want to stop|change my mind|back out/],
 ['then_what',/then what|whats next|what happens (next|after|then)|after that|what comes next/],
 ['how_long',/how long\b(?!.{0,30}\b(hear back|reply|respond|get back|been doing|has (he|ace)|have you been))|how many (hours|minutes|months|weeks|sessions|meetings|calls|times)|duration|how often|\bovertime\b|extra (time|hours?)|go(es)? over time/],
 ['what_for',/^(what|which) topics|\btopics\b|\bwhat( i)?s (it|that|this) for\b|\bwhat is (it|that) for\b|whats the point|why would i (use|need|want|book)|what do (i|you) (use|need) (it|that) for/],
 ['who_for',/do i (need|have) to be (fast|fit|in shape|a runner|good at running)|how fast (do|are) (you|they|we)|\b(from there|remotely|from (out of town|abroad|another city))\b|who( i)?s (it|that|this) for\b|who is (it|that) for\b|who can (use|book|join|come|go|attend)|is it (just |only )?for|how many (people|players|seats|spots|of us)|who gets (priority|first|in|a seat)|(?<!\badvisory\b.*)\bpriority\b|^which (members|tiers?|clients)\b|\b(advisory|clients?) (get|use|access|book)\b.{0,12}\b(truck|cybertruck|transport)\b/],
 ['how_book',/how (do|can|would) (i|you|we) (book|get|join|sign up|apply|reserve|arrange|start|rsvp|register|get tickets|get a ticket)|how does (one|it) work to book|how do i get (it|in|started)|\bdeposit\b/],
 ['when_where',/^(and )?(when|where)\b(?! (are|is) (you|he|ace|the office) open)|what (time|day|dates?)(?! (are|is|do) (you|he|ace|the office) (open|close))|whereabouts|\baddress\b|what location|which location/],
 ['what_need',/what do (i|we) need|what (should|do) (i|we) (bring|prepare|have ready|need to (bring|prepare|have))|what s required|whats required|requirements|do i need anything|what will i need/],
 ['whats_included',/what (happens|goes on|do we do|will we do) (in|at|during) (it|the|that)|is there (food|drinks?|coffee|refreshments|a talk)|do (they|you) (serve|have) (food|drinks?)|what( i)?s includ|what do (i|you|we) get|whats in it|what does it (includ|cover)|what comes with/],
 ['how_much',/how much|\bwhats (the )?(cost|price|fee|rate)|how many dollars|\bcosts?\b|\bprice\b|\bpricing\b|\b(is|are) (it|that|this|they|poker|poker night|running|the run|networking|the \w+( \w+)?) free\b|\b(do|will|would) (i|we) (need|have) to pay\b|\bcost anything\b/],
];
/* The conversational kinds can follow any topic, and need no pronoun to make
   sense ("what if I can't make one?"). The factual ones must refer back. */
const LOOSE_KINDS=new Set(['really','anything_else','why_so_much','worth_it','both','what_if','then_what']);
/* how_long needs a pronoun now ("how long is IT"): "how long is a meeting"
   names its own subject. It may still use the generic line. */
const GENERIC_OK=new Set([...LOOSE_KINDS,'how_long','what_need']);
/* A question that names its topic AND asks one narrow thing ("how much is
   the mastermind?") gets just that line, not the whole topic answer. */
const TOPIC_OF=[[/\bcommitments?\b/,'COMMITMENT'],[/\b(60 ?minutes? meeting|\$?200 meeting|the meeting)\b/,'MEETING'],[/\b(mastermind|invested aces|membership)\b/,'MASTERMIND'],[/\b(cybertruck|truck|transport|pickup)\b/,'transport'],
 [/\bpoker\b/,'poker'],[/\b(running group|run club|running)\b/,'running'],[/\bnetworking\b/,'networking'],
 [/\b(speaking|speaker|keynote)\b/,'SPEAKING'],[/\b(private advisory|advisory)\b/,'ONGOING'],[/\bworking session\b/,'start'],
 [/\b(on site|onsite) (assignment|visit)\b/,'ON_SITE']];
const NARROW=new Set(['how_much','when_where','how_book','who_for','whats_included','how_long','what_for','worth_it','what_if']);
/* Words that mean the visitor named a new subject, so it isn't a follow-up. */
/* Deliberately specific: "meeting", "session" and "event" are the words
   people use INSIDE a follow-up ("when are the meetings?"), so they can't
   count as naming a new subject. */
const NAMES_TOPIC=/\b(commitment|commitments|mastermind|membership|advisory|advisor|poker|running|networking|cybertruck|truck|transport|speaking|assignment|application|orientation|assessment|tier|tiers|working session|refund|refundable|contract|agreement|conduct|testimonials?)\b/;

const intentById=id=>INTENTS.find(i=>i.id===id);
const recordById=id=>records.find(r=>r.id===id);
const pack=(id,text,links,suggest)=>({id,text,links:links||[],suggest:suggest||[]});
/* [NEEDS INFO] intents have no answer yet: they're recognised, and answered
   with an honest hand-off until the bank's [PLACEHOLDER] is filled in. */
const fromIntent=(it,suggest)=>{const p=pack(it.id,it.answer||LINES.interim[0],it.links,suggest||it.suggest);
  if(!it.answer)p.pending=true;else if(it.alts&&it.alts.length)p.alts=it.alts;return p;};
const fromRecord=r=>pack(r.id,r.text,r.links);

/* NONSENSE / SMALL_TALK suggestions: the first from the hook table when an
   off-topic word still connects to something on the site; the rest rotate. */
const POOL=['What does Ace do?','Who is Ace?','What’s happening? Are there events?','Where do I start?','How much does it cost?','What’s a mastermind?','Can I meet Ace before committing to anything?'];
let poolAt=0;
const HOOKS=[[/\b(car|truck|drive|driver|ride|uber|lyft|taxi|airport)\b/,'What’s the Cybertruck thing?'],
 [/\b(coffee|food|eat|lunch|dinner|drink|hungry)\b/,'What happens at All Aces Networking?'],
 [/\b(run|running|jog|gym|workout|exercise|fitness|sport)\b/,'What’s the Aces Running Group?'],
 [/\b(cards|poker|gamble|casino|game night)\b/,'What’s Aces Poker Night?'],
 [/\b(travel|trip|vacation|holiday|flight|japan|abroad)\b/,'Can Ace check something out in person for me?'],
 [/\b(money|rich|crypto|stocks|lottery|invest)\b/,'Can Ace help my business grow?'],
 [/\b(stress|tired|sad|bored|motivation|lazy)\b/,'Does Ace help with the personal side?'],
 [/\b(boss|job|work|coworker|hiring)\b/,'Can Ace help with team or people problems?'],
 [/\b(talk|speech|microphone|stage|audience)\b/,'Does he do talks?'],
 [/\b(friends|lonely|meet people|community)\b/,'What’s a mastermind?']];
function suggestions(q,n){
  const out=[];const hook=HOOKS.find(h=>h[0].test(q));if(hook)out.push(hook[1]);
  while(out.length<n){const s=POOL[poolAt++%POOL.length];if(!out.includes(s))out.push(s);}
  return out;
}
/* Site vocabulary: a weak question that still uses these is on-topic, so it
   goes to Ace's Assistant (OTHER) rather than getting the nonsense line. */
const SITE=new Set(tokens('meeting session advisory advisor commitment mastermind member membership apply application event gathering poker running networking speaking transport booking business owner contact email fee assistant appointment invested aces'));

function answer(query,last){
 const q=despell(normalize(query));if(!q)return null;
 if(/suicid|kill (myself|me)|hurt myself|self harm|not safe|unsafe|end it all|dont want to (live|be here)|cant go on|crisis right now/.test(q))return fromIntent(intentById('EMERGENCY'));
 if(/^(hi|hello|hey|yo|sup|hiya|howdy|heya|greetings|good day|hello ace|hi ace|hey ace|hi little ace|good morning|good evening|good afternoon)( there)?$/.test(q))return pack('greeting','Hi, I’m Little Ace. I can help you explore private advisory, learn about Matthew, or find the right gathering. What would you like to know?',[]);
 if(/^(thanks|thank you|thx|cheers|great|awesome|perfect|ok|okay)( so much| a lot)?$/.test(q))return pack('thanks','You’re welcome. If you want to speak with Matthew about your own situation, the inquiry page is the next step.',[['Work with Ace','contact.html']]);
 if(q.includes('ignore previous')||q.includes('system prompt')||q.includes('api key'))return fromIntent(intentById('PROMPT_INJECTION'));

 const qt=tokens(q),qset=new Set(qt);
 /* Follow-up on the last answer: short, names no topic of its own, and asks
    one of the six things people ask next. Returns under the SAME topic id so
    a chain of them keeps working. */
 /* It must actually refer back: a pronoun ("what's IT for") or so short it
    can only mean the last answer ("how much?"). "Where is he based" names a
    real question of its own and must not be swallowed. */
 const aboutHim=/\b(he|him|his|ace|matthew)\b/.test(q);
 const refersBack=/\b(it|that|this|these|those|they|them|one)\b|^how many (people|players|seats|spots)\b/.test(q)||(qt.length<=2&&!aboutHim);
 const kind=qt.length<=9&&!NAMES_TOPIC.test(q)?(FOLLOW_KIND.find(f=>f[1].test(q))||[null])[0]:null;
 let followKind=kind&&(LOOSE_KINDS.has(kind)||refersBack)?kind:null;
 /* "How often?" asks when it happens, not how long it lasts. */
 if(last&&followKind==='how_long'&&/how often/.test(q)&&FOLLOWUPS[last]&&FOLLOWUPS[last].when_where)followKind='when_where';
 if(last&&followKind){
  /* "What's included?" after a topic with no included-line: what it's for. */
  const own=FOLLOWUPS[last]&&(FOLLOWUPS[last][followKind]||(followKind==='whats_included'&&FOLLOWUPS[last].what_for));
  const generic=GENERIC_OK.has(followKind)&&FOLLOWUPS.GENERIC&&FOLLOWUPS.GENERIC[followKind];
  const text=own||generic;
  if(text){const it=intentById(last),r=recordById(last);
   const p=pack(last,text,(own&&((it&&it.links)||(r&&r.links)))||[]);p.kind=followKind;return p;}
 }
 /* Named topic + one narrow ask: answer only that part. */
 const kind2=kind||(qt.length<=8?(FOLLOW_KIND.find(f=>f[1].test(q))||[null])[0]:null);
 const t0=TOPIC_OF.find(x=>x[0].test(q));
 /* "What's the member rate for the Cybertruck?" — the members line. */
 if(kind2==='both'&&qt.length<=8&&/\b(cybertruck|truck|transport|pickup)\b/.test(q)){const p=pack('transport',FOLLOWUPS.transport.both,recordById('transport').links);p.kind='both';p.narrow=true;return p;}
 if(kind2&&NARROW.has(kind2)&&qt.length<=8){
  const t=t0;
  const line=t&&FOLLOWUPS[t[1]]&&FOLLOWUPS[t[1]][kind2];
  if(line){const it=intentById(t[1]),r=recordById(t[1]);const p=pack(t[1],line,(it&&it.links)||(r&&r.links)||[]);p.kind=kind2;p.narrow=true;return p;}
 }
 /* Small talk beats scoring only when the message is short — "how's it
    going with the mastermind" must still reach the mastermind. */
 if(qt.length<=5&&/(how are you|how r u|hows it going|how s it going|nice to meet|good night|goodnight|^whats up$|^what s up$)/.test(q)&&!/\b(mastermind|advisory|meeting|member|event|business)\b/.test(q))return fromIntent(intentById('SMALL_TALK'),suggestions(q,3));
 if(last&&qt.length<=5&&/tell me more|more (info|detail)|go on|what else/.test(q)){
  const m=FOLLOW_MORE[last]&&recordById(FOLLOW_MORE[last]);if(m)return fromRecord(m);
  const it=intentById(last)||recordById(last);if(it&&it.links.length)return pack(last,'Happy to point you deeper — the pages below cover it best. Or ask me anything specific.',it.links);
 }

 const scores=new Map(),base=new Map();
 const padded=' '+q+' ';
 for(const d of docs){
  let n=0;
  for(const p of d.phrases)if(p&&padded.includes(' '+p+' '))n+=8+Math.min(p.length/6,6);
  for(const p of d.wordPhrases)if(p&&padded.includes(' '+p+' '))n+=6+Math.min(p.length/8,4);
  for(const t of qset){
   if(d.words.has(t))n+=1.6*idf(t);
   else if(t.length>=5){for(const w of d.words){if(close(t,w)){n+=0.8*idf(w);break;}}}
  }
  if(d.kind==='record')n*=0.8;   // the bank leads; records win on their specifics
  if(n>0){scores.set(d.id,(scores.get(d.id)||0)+n);base.set(d.id,(base.get(d.id)||0)+n);}
 }
 for(const rule of RULES){if(rule[0].test(q)){const adds=rule[1];for(const id in adds){
  if(scores.has(id)||adds[id]>0)scores.set(id,(scores.get(id)||0)+adds[id]);
  if(adds[id]>0&&(STRONG.has(id)||rule[2]))base.set(id,(base.get(id)||0)+adds[id]);   // pattern counts as evidence
 }}}
 let best=null,bs=0;for(const e of scores){if(e[1]>bs){bs=e[1];best=e[0];}}
 /* Runner-up: close enough that the visitor might have meant it instead.
    Offered as a "did you mean" chip, never answered. */
 let runner=null,rs=0;for(const e of scores){if(e[0]!==best&&e[1]>rs&&(base.get(e[0])||0)>0){rs=e[1];runner=e[0];}}
 if(!(rs>=6&&rs>=bs*.85&&!SAME_FAMILY(best,runner)))runner=null;

 /* Rule boosts steer between real matches; they can never invent a winner
    the question's own words did not touch. */
 if(best&&bs>=6&&(base.get(best)||0)>0){
  const it=intentById(best),r=it?null:recordById(best);
  const p=it?fromIntent(it):r?fromRecord(r):null;
  if(p){if(runner)p.runner=runner;return p;}
 }
 /* Weak match: find context before calling anything nonsense. */
 const aboutAce=/\b(ace|matthew|ferguson|he|him|his)\b/.test(q);
 const siteWord=qt.some(t=>SITE.has(t));
 /* "I want a coffee" is nonsense; "I need help with my staff" is not — so
    this only applies when nothing on the site scored at all. */
 if(!siteWord&&!aboutAce&&bs<3&&/^(i (want|need|feel like)|give me|get me|make me|buy me|bring me)\b/.test(q))return fromIntent(intentById('NONSENSE'),suggestions(q,3));
 if(aboutAce&&/\b(how old|age|birthday|favourite|favorite|married|single|girlfriend|wife|height|tattoo|pet|dog|cat|music|hobby|hobbies|net worth|salary|zodiac|smoke|drink)\b/.test(q))return fromIntent(intentById('ACE_TRIVIA'));
 if(/(how are you|how r u|hows it going|how s it going|whats up|what s up|nice to meet|you re (cute|cool|funny|nice)|lol|haha|good night|goodnight|see you|bye)/.test(q))return fromIntent(intentById('SMALL_TALK'),suggestions(q,3));
 if(best&&bs>=3&&(base.get(best)||0)>0){const it=intentById(best);if(it)return fromIntent(it);const r=recordById(best);if(r)return fromRecord(r);}
 if(siteWord||(aboutAce&&qt.length>2))return fromIntent(intentById('OTHER'));
 return fromIntent(intentById('NONSENSE'),suggestions(q,3));
}
/* Answers close enough to each other that offering one as "did you mean"
   after the other would just be noise. */
const FAMILIES=[['MASTERMIND','WHAT_IS_A_MASTERMIND','membership','membership-benefits','mastermind-schedule','JOINING','application','VS_PEER_GROUP'],
 ['CYBERTRUCK','transport','TRANSPORT_BOOKING'],['ONGOING','WHAT_IS_ADVISOR','advisory','COMMITMENT'],['WHO_IS_ACE','WHO_IS_HE','about','OWN_BUSINESS'],
 ['COST','PRICE_GENERAL','price','currency'],['EVENTS','events','MEET_INFORMALLY','EVENT_DETAILS'],['SPEAKING','SPEAKING_BOOKING','speaking'],
 ['FIRST_STEP','start','HOW_IT_WORKS','MEETING_LENGTH','MEETING'],['ON_SITE','scout'],['OVERVIEW','WHAT_IS_THIS','WHY_PEOPLE_HIRE','WHAT_IS_ADVISOR'],
 ['LITTLE_ACE','privacy','WHO_MADE_YOU','MEMORY','DOES_ACE_KNOW_YOU'],['running','RUN_DISTANCE','RUN_DOGS_KIDS'],
 ['poker','POKER_LEGAL','POKER_BEGINNER','POKER_DRINKS_AGE'],['networking','NETWORKING_DRESS','NETWORKING_REGULARS'],
 ['CONTACT','HUMAN','REPLY_TIME','PHONE'],['FIT','SIZE','WHO_FOR','NOT_AN_OWNER','MY_CASE']];
function SAME_FAMILY(a,b){return a===b||FAMILIES.some(f=>f.includes(a)&&f.includes(b));}

/* ── CONVERSATION ────────────────────────────────────────────────
   answer() above is stateless: one question in, one answer out. A Session
   wraps it with what makes a chat feel like a conversation — rotating
   wordings, remembering the visitor's name, business and budget, echoing
   their words back, the page they're on, asking a question back, and
   handling the short replies ("yes", "why?", "say that again") that only
   mean something in context. All wording comes from LINES (bank P99). */
const ABUSE=/\b(fuck|fucking|fucker|shit|shitty|bitch|asshole|cunt|dickhead|piss off|stfu|screw you|wanker|retard)\b/;
const FOREIGN=/\b(bonjour|merci|combien|pourquoi|oui|je suis|hola|gracias|cuanto|por favor|donde|necesito|hallo|danke|obrigado|ciao|grazie|ni hao|konnichiwa)\b/;
const YES=/^(yes|yeah|yea|yep|yup|sure|yes please|please|go on|go ahead|definitely|absolutely|sounds good|tell me|of course|why not)$/;
const NO=/^((no|nah|nope)[ ,]*)?(not really|no thanks|no thank you|thanks|im good|all good|thats all|thats it|nothing|none|nothing else)?$|^(no|nah|nope)$/;
const BYE=/^(bye|goodbye|good bye|see ya|see you|later|cya|good night|goodnight|take care|have a good (one|day|night)|gotta go|im off)\b/;
