   if(/^(yes|yeah|yep|yup|i do|sure|correct|both)\b|\b(my own|i own|i run|its mine|it s mine|founder|co founder|owner|self employed|freelanc|work for myself|i started|founded)\b/.test(q)){s.owner=true;s.pending=null;
    return out(pack('FIRST_STEP',(s.bizKind==='role'?'':line('owner_yes')+' ')+ownerNext(),(intentById('FIRST_STEP')||{}).links,['How much does it cost?','How do I get started?']));}
   if(/^(no|nope|nah|not really)\b|\b(work for|employee|someone else|somebody else|not my own|not mine|on a team|part of a team|staff|i work at)\b/.test(q)){s.owner=false;s.pending=null;
    return out(pack('NOT_AN_OWNER',line('biz_employee'),(intentById('NOT_AN_OWNER')||{}).links,['Can I meet Ace before committing to anything?','What’s happening? Are there events?']));}
