  if(work&&s.pending!=='biz'&&((cp&&tokens(q).length>4)||(other&&!['FIT','NONSENSE','OTHER','FIRST_STEP','OVERVIEW','SMALL_TALK','NOT_AN_OWNER','WHO_FOR','SIZE','CONTACT'].includes(other)))){s.biz=work.b;s.bizKind=work.kind;s.owner=work.owner;}
