  if(FRUSTRATED.test(q))return out(say('frustrated',null,[['Contact Ace’s Assistant','contact.html']]),{noTopic:true});
  if(REPEAT.test(q)&&s.lastText)return out(pack('line',line('repeat')+' '+s.lastText,[]),{noTopic:true,keepPending:true,keepText:true});
