  if(p.id==='WHAT_CAN_YOU_DO'){p.suggest=pool('');}
  if(p.id==='SCENARIOS')p.suggest=['Which one fits me?','More examples','How much does it cost?'];
  const r=out(decorate(p,q,raw));
  /* They were answering "tell me about your situation": go straight to
     the recommendation their answer points to. */
  if(wasSituation&&(PROBLEM.has(r.id)||DIRECT[r.id]))return out(recommendFrom('rec'));
